contract_clause_fact(contrato_ocs_298_2024, clausula_oitava_equilibrio_economico_financeiro_contrato, motivos_revisao, ['fato imprevisível', 'fato previsível, porém, de consequências incalculáveis', 'força maior', 'caso fortuito', 'fato do príncipe'], 'Parágrafo Segundo').
